<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { api, clearToken, getToken, setToken } from './api'
import ForecastView from './components/ForecastView.vue'
import AlertsView from './components/AlertsView.vue'

const user = ref(null)
const page = ref('dashboard')
const busy = ref(false)
const notice = ref('')
const authMode = ref('login')
const auth = reactive({ name: '', businessName: '', email: '', password: '' })
const demoEmail = import.meta.env.VITE_DEMO_EMAIL || ''
const demoPassword = import.meta.env.VITE_DEMO_PASSWORD || ''
const dashboard = ref(null)
const transactions = ref([])
const loadingTransactions = ref(false)
const loadingReport = ref(false)
const transactionMeta = reactive({ page: 1, pages: 1, total: 0, pageSize: 20 })
const transactionSearch = ref('')
const transactionSort = reactive({ key: 'date', direction: 'desc' })
const report = ref(null)
const filters = reactive({ from: `${new Date().toISOString().slice(0, 7)}-01`, to: new Date().toISOString().slice(0, 10), category: '', type: '' })
const settings = reactive({ name: '', businessName: '', openingBalance: 0, minimumBalance: 0 })
const preferences = reactive({ inAppAlerts: localStorage.getItem('lkumkm_in_app_alerts') !== 'false' })
const form = reactive({ type: 'income', amount: '', category: 'Penjualan', date: new Date().toISOString().slice(0, 10), description: '' })
const editingId = ref(null)
const showForm = ref(false)
const range = ref(7)
const categories = { income: ['Penjualan', 'Jasa', 'Modal', 'Lainnya'], expense: ['Bahan baku', 'Operasional', 'Gaji', 'Transportasi', 'Pemasaran', 'Lainnya'] }
const pageTitle = computed(() => ({ dashboard: 'Dashboard', transactions: 'Transaksi', forecast: 'Prediksi arus kas', alerts: 'Peringatan keuangan', reports: 'Laporan keuangan', settings: 'Pengaturan' })[page.value])
const money = (value) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(Number(value || 0))
const dateLabel = (value) => new Date(`${value}T00:00:00`).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' })
const chartData = computed(() => dashboard.value?.chart?.slice(-range.value) || [])
const chartMax = computed(() => Math.max(1, ...chartData.value.flatMap((item) => [item.income, item.expense])))
const reportDays = computed(() => {
  const grouped = new Map()
  for (const item of report.value?.daily || []) {
    if (!grouped.has(item.date)) grouped.set(item.date, { date: item.date, income: 0, expense: 0 })
    grouped.get(item.date)[item.type] = item.total
  }
  return [...grouped.values()]
})
const reportMax = computed(() => Math.max(1, ...reportDays.value.flatMap((item) => [item.income, item.expense])))

function flash(message) { notice.value = message; window.setTimeout(() => { if (notice.value === message) notice.value = '' }, 3200) }
async function loadDashboard() { dashboard.value = await api('/dashboard') }
async function loadTransactions() {
  loadingTransactions.value = true
  try {
  const query = new URLSearchParams()
  if (filters.from) query.set('from', filters.from)
  if (filters.to) query.set('to', filters.to)
  if (filters.category) query.set('category', filters.category)
  if (filters.type) query.set('type', filters.type)
  if (transactionSearch.value.trim()) query.set('q', transactionSearch.value.trim())
  query.set('page', String(transactionMeta.page))
  query.set('pageSize', String(transactionMeta.pageSize))
  query.set('sort', transactionSort.key)
  query.set('direction', transactionSort.direction)
  const result = await api(`/transactions?${query}`)
  transactions.value = result.transactions
  Object.assign(transactionMeta, { page: result.page, pages: result.pages, total: result.total, pageSize: result.pageSize })
  } catch (error) {
    transactions.value = []
    flash(error.message)
  } finally {
    loadingTransactions.value = false
  }
}
async function loadReport() {
  loadingReport.value = true
  try { const query = new URLSearchParams({ from: filters.from, to: filters.to }); report.value = await api(`/reports?${query}`) }
  catch (error) { report.value = null; flash(error.message) }
  finally { loadingReport.value = false }
}
async function refresh() {
  if (!user.value) return
  try {
    await loadDashboard()
    if (page.value === 'transactions') await loadTransactions()
    if (page.value === 'reports') await loadReport()
  } catch (error) { flash(error.message); if (!getToken()) user.value = null }
}
async function openPage(next) {
  page.value = next
  try {
    if (next === 'transactions') { transactionMeta.page = 1; await loadTransactions() }
    if (next === 'reports') await loadReport()
    if (next === 'settings') Object.assign(settings, user.value)
  } catch (error) { flash(error.message) }
}
async function searchTransactions() { transactionMeta.page = 1; await loadTransactions() }
async function sortTransactions(key) {
  transactionSort.direction = transactionSort.key === key && transactionSort.direction === 'asc' ? 'desc' : 'asc'
  transactionSort.key = key
  transactionMeta.page = 1
  await loadTransactions()
}
async function setTransactionPage(next) { transactionMeta.page = Math.min(transactionMeta.pages, Math.max(1, next)); await loadTransactions() }
async function submitAuth() {
  busy.value = true
  try {
    const path = authMode.value === 'login' ? '/auth/login' : '/auth/register'
    const body = authMode.value === 'login' ? { email: auth.email, password: auth.password } : { ...auth }
    const data = await api(path, { method: 'POST', body: JSON.stringify(body) })
    setToken(data.token); user.value = data.user; await refresh()
  } catch (error) { flash(error.message) } finally { busy.value = false }
}
function useDemoAccount() {
  auth.email = demoEmail
  auth.password = demoPassword
  submitAuth()
}
async function logout() {
  try { await api('/auth/logout', { method: 'POST' }) } catch { /* local session is always cleared */ }
  clearToken(); user.value = null; dashboard.value = null; page.value = 'dashboard'
}
function newTransaction() {
  editingId.value = null
  Object.assign(form, { type: 'income', amount: '', category: 'Penjualan', date: new Date().toISOString().slice(0, 10), description: '' })
  showForm.value = true
}
function editTransaction(item) {
  editingId.value = item.id
  Object.assign(form, { type: item.type, amount: item.amount, category: item.category, date: item.date, description: item.description })
  showForm.value = true
}
async function saveTransaction() {
  busy.value = true
  try {
    const path = editingId.value ? `/transactions/${editingId.value}` : '/transactions'
    await api(path, { method: editingId.value ? 'PUT' : 'POST', body: JSON.stringify({ ...form, amount: Number(form.amount) }) })
    showForm.value = false; await loadTransactions(); await loadDashboard(); flash('Transaksi berhasil disimpan.')
  } catch (error) { flash(error.message) } finally { busy.value = false }
}
async function deleteTransaction(item) {
  if (!window.confirm(`Hapus transaksi “${item.description || item.category}”?`)) return
  try { await api(`/transactions/${item.id}`, { method: 'DELETE' }); await loadTransactions(); await loadDashboard(); flash('Transaksi dihapus.') } catch (error) { flash(error.message) }
}
async function saveSettings() {
  try {
    const data = await api('/settings', { method: 'PUT', body: JSON.stringify(settings) })
    user.value = data.user; await loadDashboard(); flash('Pengaturan berhasil disimpan.')
  } catch (error) { flash(error.message) }
}
function savePreferences() {
  localStorage.setItem('lkumkm_in_app_alerts', String(preferences.inAppAlerts))
  flash('Preferensi peringatan disimpan di perangkat ini.')
}
function exportCsv() {
  if (!report.value) return
  const rows = [['Tanggal','Jenis','Kategori','Catatan','Nominal'], ...report.value.transactions.map((item) => [item.date, item.type === 'income' ? 'Pemasukan' : 'Pengeluaran', item.category, item.description, item.amount])]
  const csv = rows.map((row) => row.map((cell) => `"${String(cell).replaceAll('"', '""')}"`).join(',')).join('\n')
  const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8' })); link.download = 'laporan-keuangan-lkumkm.csv'; link.click(); URL.revokeObjectURL(link.href)
}
onMounted(async () => {
  if (!getToken()) return
  try { const data = await api('/me'); user.value = data.user; await refresh() } catch { clearToken() }
})
</script>

<template>
  <main v-if="!user" class="auth-page">
    <div class="auth-brand"><div class="brand-mark">L</div><span>LK<span>UMKM</span></span></div>
    <section class="auth-card">
      <div class="eyebrow">KEUANGAN USAHA LEBIH JELAS</div>
      <h1>{{ authMode === 'login' ? 'Selamat datang kembali' : 'Mulai kelola usahamu' }}</h1>
      <p class="muted">{{ authMode === 'login' ? 'Masuk untuk melihat kondisi keuangan usaha.' : 'Buat akun usaha dan catat transaksi pertamamu.' }}</p>
      <form @submit.prevent="submitAuth">
        <label v-if="authMode === 'register'">Nama pemilik<input v-model="auth.name" required placeholder="Nama lengkap"></label>
        <label v-if="authMode === 'register'">Nama usaha<input v-model="auth.businessName" placeholder="Contoh: Kedai Pagi"></label>
        <label>Email<input v-model="auth.email" type="email" required autocomplete="email" placeholder="nama@email.com"></label>
        <label>Kata sandi<input v-model="auth.password" type="password" required minlength="8" autocomplete="current-password" placeholder="Minimal 8 karakter"></label>
        <button class="button primary full" :disabled="busy">{{ busy ? 'Memproses…' : authMode === 'login' ? 'Masuk ke dashboard' : 'Buat akun' }}</button>
      </form>
      <div v-if="authMode === 'login' && demoEmail" class="demo-access"><span>Ingin melihat contoh?</span><button class="button secondary full" :disabled="busy" @click="useDemoAccount">Masuk dengan akun demo</button><small>Akun ini berisi transaksi simulasi, bukan data usaha nyata.</small></div>
      <p class="switch-auth">{{ authMode === 'login' ? 'Belum punya akun?' : 'Sudah punya akun?' }} <button @click="authMode = authMode === 'login' ? 'register' : 'login'">{{ authMode === 'login' ? 'Daftar sekarang' : 'Masuk' }}</button></p>
    </section>
    <p class="auth-foot">Data keuanganmu tersimpan secara pribadi untuk akun ini.</p>
    <div v-if="notice" class="toast">{{ notice }}</div>
  </main>

  <div v-else class="app-shell">
    <aside class="sidebar">
      <div class="brand"><div class="brand-mark">L</div><span>LK<span>UMKM</span></span></div>
      <div class="side-caption">MENU UTAMA</div>
      <nav>
        <button :class="{active: page === 'dashboard'}" @click="openPage('dashboard')"><span class="nav-icon">▦</span>Dashboard</button>
        <button :class="{active: page === 'transactions'}" @click="openPage('transactions')"><span class="nav-icon">↔</span>Transaksi</button>
        <button :class="{active: page === 'forecast'}" @click="openPage('forecast')"><span class="nav-icon">↗</span>Prediksi arus kas</button>
        <button :class="{active: page === 'alerts'}" @click="openPage('alerts')"><span class="nav-icon">!</span>Peringatan keuangan</button>
        <button :class="{active: page === 'reports'}" @click="openPage('reports')"><span class="nav-icon">▤</span>Laporan</button>
      </nav>
      <div class="side-caption side-settings">PREFERENSI</div>
      <nav><button :class="{active: page === 'settings'}" @click="openPage('settings')"><span class="nav-icon">⚙</span>Pengaturan</button></nav>
    </aside>

    <section class="workspace">
      <header class="topbar"><div class="topbar-heading"><div><div class="breadcrumb">LKUMKM <span>/</span> {{ pageTitle }}</div><h1>{{ pageTitle }}</h1></div></div><div class="top-actions"><span class="today">{{ new Date().toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }) }}</span><details class="notification-menu"><summary class="notification-button" :aria-label="dashboard?.activeWarnings ? `${dashboard.activeWarnings} peringatan keuangan` : 'Tidak ada peringatan keuangan'" title="Peringatan keuangan"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg><span v-if="preferences.inAppAlerts && dashboard?.activeWarnings" class="notification-count">{{ dashboard.activeWarnings }}</span></summary><div class="notification-dropdown"><div class="notification-dropdown-heading"><strong>Notifikasi</strong><span v-if="preferences.inAppAlerts && dashboard?.activeWarnings">{{ dashboard.activeWarnings }} aktif</span></div><div v-if="dashboard?.alert" class="notification-item"><span class="notification-item-icon">!</span><div><strong>Potensi kekurangan kas</strong><p>{{ dashboard.alert.reason }}</p><small>Perkiraan {{ dateLabel(dashboard.alert.date) }}</small></div></div><div v-else class="notification-empty">Belum ada peringatan keuangan.</div><button class="notification-all" @click="openPage('alerts'); $event.currentTarget.closest('details').open = false">Lihat semua peringatan <span>→</span></button></div></details><details class="profile-menu"><summary :aria-label="`Profil ${user.name}`"><span class="profile-avatar">{{ user.name.slice(0,1).toUpperCase() }}</span><span class="profile-label"><strong>{{ user.name }}</strong><small>{{ user.businessName }}</small></span><span class="profile-chevron">⌄</span></summary><div class="profile-dropdown"><div class="profile-dropdown-heading"><span class="profile-avatar">{{ user.name.slice(0,1).toUpperCase() }}</span><span><strong>{{ user.name }}</strong><small>{{ user.businessName }}</small></span></div><button class="profile-logout" @click="$event.currentTarget.closest('details').open = false; logout()">Keluar <span>↪</span></button></div></details></div></header>

      <ForecastView v-if="page === 'forecast'" @notice="flash" />
      <AlertsView v-else-if="page === 'alerts'" @settings="openPage('settings')" @notice="flash" />

      <div v-if="page === 'dashboard' && dashboard" class="content">
        <div class="welcome-row"><div><h2>Selamat datang, {{ user.name.split(' ')[0] }}</h2><p>{{ user.businessName }} · Ringkasan kondisi keuangan usahamu.</p></div><span class="live-pill"><i></i> Data tersinkron</span></div>
        <div class="metric-grid">
          <article class="metric-card balance-card"><div class="metric-top"><span>Saldo kas saat ini</span><span class="metric-icon green-icon">◉</span></div><strong>{{ money(dashboard.currentBalance) }}</strong><small>Termasuk saldo awal dan seluruh transaksi</small><div class="balance-accent"></div></article>
          <article class="metric-card"><div class="metric-top"><span>Pemasukan bulan ini</span><span class="metric-icon income-icon">↗</span></div><strong>{{ money(dashboard.income) }}</strong><small class="positive">● Periode bulan berjalan</small></article>
          <article class="metric-card"><div class="metric-top"><span>Pengeluaran bulan ini</span><span class="metric-icon expense-icon">↘</span></div><strong>{{ money(dashboard.expense) }}</strong><small>Periode bulan berjalan</small></article>
          <article class="metric-card"><div class="metric-top"><span>Laba / rugi bulan ini</span><span class="metric-icon profit-icon">◒</span></div><strong :class="dashboard.profit >= 0 ? 'text-green' : 'text-red'">{{ money(dashboard.profit) }}</strong><small>{{ dashboard.profit >= 0 ? 'Pemasukan lebih besar dari pengeluaran' : 'Pengeluaran lebih besar dari pemasukan' }}</small></article>
        </div>
        <div class="main-grid">
          <article class="panel chart-panel"><div class="panel-heading"><div><h3>Arus kas</h3><p>Pergerakan bersih transaksi harian</p></div><select v-model.number="range" class="select-small"><option :value="7">7 hari</option><option :value="14">14 hari</option><option :value="30">30 hari</option></select></div>
            <div v-if="chartData.some(d => d.income !== 0 || d.expense !== 0)" class="chart-canvas chart-bars"><div v-for="item in chartData" :key="item.date" class="flow-day"><div class="flow-bars"><i class="flow-bar income-bar" :style="{height: `${Math.max(3, item.income / chartMax * 100)}%`}" :title="money(item.income)"></i><i class="flow-bar expense-bar" :style="{height: `${Math.max(3, item.expense / chartMax * 100)}%`}" :title="money(item.expense)"></i></div><small>{{ item.date.slice(-2) }}</small></div></div>
            <div v-else class="empty-chart"><div class="empty-icon">↗</div><strong>Grafik akan muncul setelah ada transaksi</strong><span>Catat pemasukan atau pengeluaran pertamamu.</span><button class="text-button" @click="newTransaction">＋ Catat transaksi</button></div>
            <div class="chart-legend"><span><i class="legend-dot green-dot"></i> Pemasukan</span><span><i class="legend-dot expense-dot"></i> Pengeluaran</span></div>
          </article>
          <article class="panel forecast-panel"><div class="panel-heading"><div><h3>Prediksi saldo</h3><p>Berdasarkan 30 hari terakhir</p></div><button class="text-button" @click="openPage('forecast')">Lihat detail <span>→</span></button></div><template v-if="dashboard.sufficientHistory"><div v-for="item in dashboard.forecast" :key="item.days" class="forecast-row"><span>{{ item.days }} hari ke depan</span><strong :class="item.balance >= user.minimumBalance ? 'text-green' : 'text-red'">{{ money(item.balance) }}</strong></div></template><div v-else class="forecast-row"><span>Data belum cukup</span><small>Transaksi tercatat pada {{ dashboard.historyDays }} hari berbeda; perlu minimal 7 hari.</small></div><div class="method-note"><span>i</span><p>Perkiraan memakai rata-rata arus kas harian 30 hari terakhir, seolah pola itu berulang. Ini bukan kepastian dan belum memperhitungkan perubahan mendatang.</p></div></article>
        </div>
        <article v-if="dashboard.alert" class="alert-card"><div class="alert-symbol">!</div><div class="alert-copy"><div class="alert-title">Potensi kekurangan kas · {{ dashboard.alert.urgency }}</div><p>{{ dashboard.alert.reason }}</p><small>Perkiraan tanggal {{ dateLabel(dashboard.alert.date) }} · Proyeksi {{ money(dashboard.alert.projectedBalance) }}</small></div><button @click="openPage('alerts')">Lihat peringatan <span>→</span></button></article>
        <article v-else class="safe-card"><span class="safe-check">{{ dashboard.sufficientHistory ? '✓' : 'i' }}</span><div><strong>{{ dashboard.sufficientHistory ? 'Tidak ada indikasi risiko dari pola terakhir' : 'Data prediksi belum cukup' }}</strong><p>{{ dashboard.sufficientHistory ? `Rata-rata 30 hari terakhir memproyeksikan saldo di atas batas minimum ${money(user.minimumBalance)}. Ini perkiraan, bukan jaminan.` : `Transaksi tercatat pada ${dashboard.historyDays} hari berbeda; perlu minimal 7 hari untuk menampilkan prediksi.` }}</p></div><button @click="openPage('alerts')">Lihat status kas</button></article>
        <article class="panel recent-panel"><div class="panel-heading"><div><h3>Transaksi terbaru</h3><p>Catatan keuangan usahamu</p></div><button class="text-button" @click="openPage('transactions')">Lihat semua <span>→</span></button></div><div v-if="dashboard.recent.length" class="table-wrap"><table><thead><tr><th>TRANSAKSI</th><th>KATEGORI</th><th>TANGGAL</th><th class="align-right">NOMINAL</th></tr></thead><tbody><tr v-for="item in dashboard.recent" :key="item.id"><td><span class="transaction-dot" :class="item.type"></span><span class="transaction-name">{{ item.description || item.category }}</span></td><td><span class="category-chip">{{ item.category }}</span></td><td class="date-cell">{{ dateLabel(item.date) }}</td><td class="align-right amount-cell" :class="item.type === 'income' ? 'text-green' : 'text-default'">{{ item.type === 'income' ? '+' : '−' }} {{ money(item.amount) }}</td></tr></tbody></table></div><div v-else class="empty-table">Belum ada transaksi. Semua transaksi yang kamu catat akan muncul di sini.</div></article>
      </div>

      <div v-else-if="page === 'transactions'" class="content">
        <div class="page-intro"><div><div class="eyebrow">CATATAN KEUANGAN</div><h2>Transaksi</h2><p>Cari, tinjau, dan kelola pemasukan serta pengeluaran usaha.</p></div><button class="button primary" @click="newTransaction">+ Tambah transaksi</button></div>
        <form class="transaction-search" @submit.prevent="searchTransactions"><label class="search-field"><span class="sr-only">Cari deskripsi transaksi</span><input v-model="transactionSearch" placeholder="Cari deskripsi transaksi…"></label><button class="button secondary">Cari</button></form>
        <article class="panel filter-panel"><label>Dari tanggal<input v-model="filters.from" type="date" @change="transactionMeta.page=1; loadTransactions()"></label><label>Sampai tanggal<input v-model="filters.to" type="date" @change="transactionMeta.page=1; loadTransactions()"></label><label>Jenis<select v-model="filters.type" @change="transactionMeta.page=1; loadTransactions()"><option value="">Semua jenis</option><option value="income">Pemasukan</option><option value="expense">Pengeluaran</option></select></label><label>Kategori<select v-model="filters.category" @change="transactionMeta.page=1; loadTransactions()"><option value="">Semua kategori</option><option v-for="(category, index) in [...new Set([...categories.income, ...categories.expense])]" :key="`${category}-${index}`">{{ category }}</option></select></label></article>
        <article class="panel table-panel"><div class="panel-heading"><div><h3>Daftar transaksi</h3><p>{{ loadingTransactions ? 'Memuat transaksi…' : transactionMeta.total + ' catatan' }} · halaman {{ transactionMeta.page }} dari {{ transactionMeta.pages }}</p></div></div><div class="table-wrap"><table><thead><tr><th>TRANSAKSI</th><th><button class="sort-button" @click="sortTransactions('type')">JENIS <span>{{ transactionSort.key === 'type' ? (transactionSort.direction === 'asc' ? '↑' : '↓') : '↕' }}</span></button></th><th><button class="sort-button" @click="sortTransactions('category')">KATEGORI <span>{{ transactionSort.key === 'category' ? (transactionSort.direction === 'asc' ? '↑' : '↓') : '↕' }}</span></button></th><th><button class="sort-button" @click="sortTransactions('date')">TANGGAL <span>{{ transactionSort.key === 'date' ? (transactionSort.direction === 'asc' ? '↑' : '↓') : '↕' }}</span></button></th><th class="align-right"><button class="sort-button" @click="sortTransactions('amount')">NOMINAL <span>{{ transactionSort.key === 'amount' ? (transactionSort.direction === 'asc' ? '↑' : '↓') : '↕' }}</span></button></th><th></th></tr></thead><tbody><tr v-for="item in transactions" :key="item.id"><td class="transaction-name">{{ item.description || item.category }}</td><td><span class="type-chip" :class="item.type">{{ item.type === 'income' ? 'Pemasukan' : 'Pengeluaran' }}</span></td><td><span class="category-chip">{{ item.category }}</span></td><td class="date-cell">{{ dateLabel(item.date) }}</td><td class="align-right amount-cell" :class="item.type === 'income' ? 'text-green' : 'text-default'">{{ item.type === 'income' ? '+' : '−' }} {{ money(item.amount) }}</td><td class="row-actions"><button @click="editTransaction(item)">Ubah</button><button @click="deleteTransaction(item)">Hapus</button></td></tr></tbody></table><div v-if="!transactions.length" class="empty-table">{{ transactionSearch ? 'Tidak ada transaksi yang cocok dengan pencarian.' : 'Belum ada transaksi pada periode ini.' }}</div></div><div v-if="transactionMeta.pages > 1" class="pagination"><span>Menampilkan {{ transactions.length }} dari {{ transactionMeta.total }} transaksi</span><div><button class="button secondary" :disabled="transactionMeta.page <= 1" @click="setTransactionPage(transactionMeta.page - 1)">Sebelumnya</button><span>{{ transactionMeta.page }} / {{ transactionMeta.pages }}</span><button class="button secondary" :disabled="transactionMeta.page >= transactionMeta.pages" @click="setTransactionPage(transactionMeta.page + 1)">Berikutnya</button></div></div></article>
      </div>

      <div v-else-if="page === 'reports'" class="content report-page">
        <div class="page-intro"><div><div class="eyebrow">ANALISIS USAHA</div><h2>Laporan keuangan</h2><p>Ringkasan pemasukan, pengeluaran, dan pergerakan kas pada periode terpilih.</p></div><button class="button secondary" @click="exportCsv">Unduh CSV</button></div>
        <form class="panel filter-panel report-filter" @submit.prevent="loadReport"><label>Dari tanggal<input v-model="filters.from" type="date"></label><label>Sampai tanggal<input v-model="filters.to" type="date"></label><button class="button primary">Tampilkan laporan</button></form>
        <div v-if="loadingReport" class="panel loading-state">Memuat laporan…</div>
        <template v-if="report">
          <div class="metric-grid report-metrics">
            <article class="metric-card"><div class="metric-top"><span>Total pemasukan</span><span class="metric-icon income-icon">↗</span></div><strong>{{ money(report.summary.income) }}</strong><small>{{ dateLabel(report.from) }} – {{ dateLabel(report.to) }}</small></article>
            <article class="metric-card"><div class="metric-top"><span>Total pengeluaran</span><span class="metric-icon expense-icon">↘</span></div><strong>{{ money(report.summary.expense) }}</strong><small>{{ dateLabel(report.from) }} – {{ dateLabel(report.to) }}</small></article>
            <article class="metric-card"><div class="metric-top"><span>Laba / rugi periode</span><span class="metric-icon profit-icon">±</span></div><strong :class="report.summary.profit >= 0 ? 'text-green' : 'text-red'">{{ money(report.summary.profit) }}</strong><small>Selisih pemasukan dan pengeluaran</small></article>
            <article class="metric-card"><div class="metric-top"><span>Saldo akhir</span><span class="metric-icon green-icon">▣</span></div><strong>{{ money(report.summary.endingBalance) }}</strong><small>Saldo sampai akhir periode</small></article>
          </div>
          <div class="report-detail-grid">
            <article class="panel report-chart-panel"><div class="panel-heading"><div><h3>Arus kas harian</h3><p>Perbandingan pemasukan dan pengeluaran</p></div></div><div v-if="reportDays.length" class="report-chart report-flow-chart"><div v-for="item in reportDays" :key="item.date" class="report-flow-day"><div class="report-flow-bars"><i class="flow-bar income-bar" :style="{height: `${Math.max(3, item.income / reportMax * 100)}%`}" :title="money(item.income)"></i><i class="flow-bar expense-bar" :style="{height: `${Math.max(3, item.expense / reportMax * 100)}%`}" :title="money(item.expense)"></i></div><small>{{ item.date.slice(-2) }}</small></div></div><div v-else class="empty-table">Belum ada transaksi pada periode ini.</div></article>
            <article class="panel category-panel"><div class="panel-heading"><div><h3>Pengeluaran per kategori</h3><p>Rincian biaya selama periode ini</p></div></div><div v-if="report.expenseBreakdown.length" class="category-breakdown"><div v-for="item in report.expenseBreakdown" :key="item.category" class="breakdown-row"><div><span>{{ item.category }}</span><strong>{{ money(item.total) }}</strong></div><div class="breakdown-track"><i :style="{ width: (item.total / Math.max(...report.expenseBreakdown.map((row) => row.total))) * 100 + '%' }"></i></div></div></div><div v-else class="empty-table">Belum ada pengeluaran pada periode ini.</div></article>
          </div>
          <article class="panel comparison-panel"><div class="panel-heading"><div><h3>Prediksi dibanding realisasi</h3><p>Prediksi memakai rata-rata arus kas bersih 30 hari sebelum periode.</p></div></div><div class="comparison-values"><div><small>Prediksi laba / rugi</small><strong>{{ money(report.comparison.forecastProfit) }}</strong></div><span class="comparison-arrow">→</span><div><small>Realisasi laba / rugi</small><strong :class="report.comparison.actualProfit >= 0 ? 'text-green' : 'text-red'">{{ money(report.comparison.actualProfit) }}</strong></div><div class="variance"><small>Selisih prediksi dan realisasi</small><strong :class="report.comparison.variance >= 0 ? 'text-green' : 'text-red'">{{ money(report.comparison.variance) }}</strong></div></div></article>
          <article class="panel table-panel"><div class="panel-heading"><div><h3>Rincian transaksi</h3><p>{{ report.transactions.length }} transaksi · {{ dateLabel(report.from) }} – {{ dateLabel(report.to) }}</p></div></div><div class="table-wrap"><table><thead><tr><th>TANGGAL</th><th>JENIS</th><th>KATEGORI</th><th>CATATAN</th><th class="align-right">NOMINAL</th></tr></thead><tbody><tr v-for="item in report.transactions" :key="item.id"><td class="date-cell">{{ dateLabel(item.date) }}</td><td>{{ item.type === 'income' ? 'Pemasukan' : 'Pengeluaran' }}</td><td><span class="category-chip">{{ item.category }}</span></td><td>{{ item.description || '—' }}</td><td class="align-right amount-cell" :class="item.type === 'income' ? 'text-green' : 'text-default'">{{ money(item.amount) }}</td></tr></tbody></table><div v-if="!report.transactions.length" class="empty-table">Belum ada catatan pada periode ini.</div></div></article>
        </template>
      </div>

      <div v-else-if="page === 'settings'" class="content settings-content">
        <div class="page-intro"><div><div class="eyebrow">PREFERENSI USAHA</div><h2>Pengaturan</h2><p>Kelola profil, saldo, kategori, dan preferensi peringatan.</p></div></div>
        <form class="panel settings-form" @submit.prevent="saveSettings">
          <div class="settings-section"><span class="section-mark">01</span><div class="settings-fields"><h3>Profil usaha</h3><p>Informasi pemilik dan usaha yang ditampilkan pada akun.</p><div class="field-grid"><label>Nama pemilik<input v-model="settings.name" required></label><label>Nama usaha<input v-model="settings.businessName" required></label></div></div></div>
          <div class="settings-section"><span class="section-mark">02</span><div class="settings-fields"><h3>Saldo dan peringatan kas</h3><p>Nilai ini dipakai untuk menghitung saldo berjalan dan mendeteksi risiko.</p><div class="field-grid"><label>Saldo awal usaha<div class="input-prefix"><span>Rp</span><input v-model.number="settings.openingBalance" type="number" min="0" step="1000" required></div><small>Saldo sebelum transaksi dicatat di aplikasi.</small></label><label>Batas minimum kas<div class="input-prefix"><span>Rp</span><input v-model.number="settings.minimumBalance" type="number" min="0" step="1000" required></div><small>Peringatan muncul saat proyeksi turun di bawah batas ini.</small></label></div></div></div>
          <div class="settings-actions"><span>Perubahan langsung digunakan pada dashboard.</span><button class="button primary">Simpan pengaturan</button></div>
        </form>
        <article class="panel settings-extra"><div class="settings-section-title"><span class="section-mark">03</span><div><h3>Kategori transaksi</h3><p>Kategori berikut tersedia saat mencatat transaksi.</p></div></div><div class="category-settings"><div><strong>Pemasukan</strong><span v-for="category in categories.income" :key="`in-${category}`" class="category-chip">{{ category }}</span></div><div><strong>Pengeluaran</strong><span v-for="category in categories.expense" :key="`out-${category}`" class="category-chip">{{ category }}</span></div></div><small class="settings-note">Kategori khusus belum dapat ditambahkan.</small></article>
        <article class="panel settings-extra notification-settings"><div class="settings-section-title"><span class="section-mark">04</span><div><h3>Preferensi peringatan</h3><p>Kontrol indikator peringatan pada header di perangkat ini.</p></div></div><label class="switch-row"><span><strong>Peringatan dalam aplikasi</strong><small>Menampilkan indikator saat ada risiko kas aktif.</small></span><input v-model="preferences.inAppAlerts" type="checkbox" @change="savePreferences"></label></article>
        <div class="privacy-note"><span>i</span><p><strong>Data usaha bersifat pribadi.</strong><br>Transaksi hanya bisa dilihat oleh akun pemiliknya.</p></div>
      </div>

      <footer class="footer">LKUMKM <span>·</span> Kelola usaha dengan lebih tenang.</footer>
    </section>

    <div v-if="showForm" class="modal-backdrop" @click.self="showForm = false"><form class="modal" @submit.prevent="saveTransaction"><div class="modal-head"><div><div class="eyebrow">CATATAN KEUANGAN</div><h2>{{ editingId ? 'Ubah transaksi' : 'Transaksi baru' }}</h2></div><button type="button" class="close-button" @click="showForm = false">×</button></div><div class="type-toggle"><button type="button" :class="{selected: form.type === 'income'}" @click="form.type = 'income'; form.category = categories.income[0]">↗ Pemasukan</button><button type="button" :class="{selected: form.type === 'expense'}" @click="form.type = 'expense'; form.category = categories.expense[0]">↘ Pengeluaran</button></div><label>Nominal transaksi<div class="input-prefix amount-input"><span>Rp</span><input v-model="form.amount" type="number" min="1" step="1" required placeholder="0"></div></label><div class="field-grid"><label>Kategori<select v-model="form.category"><option v-for="category in categories[form.type]" :key="category">{{ category }}</option></select></label><label>Tanggal<input v-model="form.date" type="date" required></label></div><label>Catatan <span class="optional">(opsional)</span><input v-model="form.description" maxlength="255" placeholder="Contoh: Penjualan hari ini"></label><div class="modal-actions"><button type="button" class="button secondary" @click="showForm = false">Batal</button><button class="button primary" :disabled="busy">{{ busy ? 'Menyimpan…' : 'Simpan transaksi' }}</button></div></form></div>
    <div v-if="notice" class="toast">{{ notice }}</div>
  </div>
</template>

